//! Actual B14010 path binding insertion and AFF610 growth by eight references.
use crate::{audio_bus_bank::Error,audio_plugin_factory::Memory,audio_frame_node_update::Runtime as Nodes,audio_timed_node_update::Runtime as Bindings};
fn word(r:&[u8],o:usize)->u32{u32::from_le_bytes(r[o..o+4].try_into().unwrap())}
fn set(r:&mut[u8],o:usize,v:u32){r[o..o+4].copy_from_slice(&v.to_le_bytes());}
pub trait Services{fn allocate(&mut self,pool:u32,bytes:u32)->Result<Option<Memory>,Error>;fn free(&mut self,pool:u32,memory:&Memory)->Result<(),Error>;}
pub fn register(nodes:&mut Nodes,bindings:&mut Bindings,reference:u32,key:u32,pool:u32,services:&mut impl Services)->Result<u32,Error>{
 let n=nodes.nodes.get_mut(&reference).ok_or(Error::UnresolvedReference)?;if reference==0||n.reference!=reference||n.raw.len()<108{return Err(Error::InvalidAllocation);}let count=word(&n.raw,36);if count>=8{return Ok(2);}let mut base=word(&n.raw,32);let capacity=word(&n.raw,40);
 if count>capacity{return Err(Error::InvalidAllocation);}if base!=0{let m=bindings.tables.get(&base).ok_or(Error::UnresolvedReference)?;if m.reference!=base||m.raw.len()<(capacity as usize).checked_mul(4).ok_or(Error::InvalidAllocation)?{return Err(Error::InvalidAllocation);}if(0..count as usize).any(|i|word(&m.raw,i*4)==key){return Ok(40);}}else if capacity!=0||count!=0{return Err(Error::InvalidAllocation);}
 if count>=capacity{let next_capacity=capacity.checked_add(8).ok_or(Error::InvalidAllocation)?;let size=next_capacity.checked_mul(4).ok_or(Error::InvalidAllocation)?;let Some(mut next)=services.allocate(pool,size)?else{return Ok(40);};if next.reference==0||next.raw.len()!=size as usize||bindings.tables.contains_key(&next.reference){return Err(Error::InvalidAllocation);}if base!=0{let old=&bindings.tables[&base];next.raw[..count as usize*4].copy_from_slice(&old.raw[..count as usize*4]);services.free(pool,old)?;bindings.tables.remove(&base);}base=next.reference;bindings.tables.insert(base,next);set(&mut n.raw,32,base);set(&mut n.raw,40,next_capacity);}
 let m=bindings.tables.get_mut(&base).ok_or(Error::UnresolvedReference)?;set(&mut m.raw,count as usize*4,key);set(&mut n.raw,36,count+1);n.raw[45]=n.raw[45].wrapping_add(1);Ok(1)
}
#[cfg(test)]mod tests{
 use super::*;use std::collections::BTreeMap;use serde_json::{Value,json};
 fn bytes(s:&str)->Vec<u8>{(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()}
 fn hex(b:&[u8])->String{b.iter().map(|v|format!("{v:02x}")).collect()}
 struct Backend{failure:bool,pattern:u8,calls:Vec<Value>,freed:BTreeMap<u32,Memory>,allocated:Vec<u32>}
 impl Services for Backend{fn allocate(&mut self,pool:u32,bytes:u32)->Result<Option<Memory>,Error>{let reference=if self.failure{0}else{0x4000a000};self.calls.push(json!({"kind":"allocate","pool":pool,"bytes":bytes,"reference":reference}));if reference==0{return Ok(None);}self.allocated.push(reference);Ok(Some(Memory{reference,raw:vec![self.pattern;bytes as usize]}))}fn free(&mut self,pool:u32,m:&Memory)->Result<(),Error>{self.calls.push(json!({"kind":"free","pool":pool,"reference":m.reference}));self.freed.insert(m.reference,m.clone());Ok(())}}
 #[test]fn audio_path_binding_registration_matches240_native_ceiling_duplicate_null_growth_oom_and_byte_wrap_cases(){let p:Value=serde_json::from_str(include_str!("../../../data/4.20/audio_path_binding_registration_preparation.json")).unwrap();assert_eq!(p["passed"],true);assert_eq!(p["case_count"],240);for(i,row)in p["cases"].as_array().unwrap().iter().enumerate(){let b=&row["before"];let raw=bytes(b["node"].as_str().unwrap());let pattern=raw[44];let initial=b["allocations"].as_array().unwrap();let mut nodes=Nodes{reference:0,header:[0;12],table:Memory{reference:0,raw:vec![]},nodes:BTreeMap::from([(0x40006000,Memory{reference:0x40006000,raw})])};let mut bindings=Bindings{tables:initial.iter().map(|a|{let reference=a["reference"].as_u64().unwrap()as u32;(reference,Memory{reference,raw:bytes(a["raw"].as_str().unwrap())})}).collect(),..Bindings::default()};let failure=row["calls"].as_array().unwrap().iter().any(|v|v["kind"]=="allocate"&&v["reference"]==0);let mut backend=Backend{failure,pattern,calls:vec![],freed:BTreeMap::new(),allocated:vec![]};let result=register(&mut nodes,&mut bindings,0x40006000,row["key"].as_u64().unwrap()as u32,17,&mut backend).unwrap();assert_eq!(result,row["result"].as_u64().unwrap()as u32,"status {i}");assert_eq!(json!(backend.calls),row["calls"],"allocation/free order {i}");let refs:Vec<u32>=initial.iter().map(|v|v["reference"].as_u64().unwrap()as u32).chain(backend.allocated.iter().copied()).collect();let allocations:Vec<Value>=refs.into_iter().map(|reference|{let m=backend.freed.get(&reference).or_else(||bindings.tables.get(&reference)).unwrap();json!({"reference":reference,"raw":hex(&m.raw),"freed":backend.freed.contains_key(&reference)})}).collect();assert_eq!(json!({"node":hex(&nodes.nodes[&0x40006000].raw),"allocations":allocations}),row["after"],"all storage and ownership {i}");}}
}
